53	static struct property_t *disp_get_board_config(const char *main_name, u32 *len)
54	{
55		struct property_t *cur = NULL;
56	
57		if (!main_name || !len) {
58			goto OUT;
59		}
60	
61		if (!strcmp(main_name, "lcd0")) {
62			cur = g_lcd0_config;
63			*len = g_lcd0_config_len;
64		} else if (!strcmp(main_name, "lcd1")) {
65			cur = g_lcd1_config;
66			*len = g_lcd1_config_len;
67		} else if (!strcmp(main_name, "disp")) {
68			cur = g_disp_config;
69			*len = g_disp_config_len;
70		} else {
71			cur = g_lcd0_config_list[atoi(&main_name[10])];
72			*len = g_lcd0_config_len_list[atoi(&main_name[10])];
73		}
74	OUT:
75		return cur;
76	}
77	
78	u32 disp_get_property_value(const char *main_name, const char *sub_name, void *value)
79	{
80		u32 i = 0, len = 0;
81		struct property_t *cur = NULL;
82	
83	#if (RTOS_SYS_CONFIG_USE == 1)
84		return 0;
85	#else
86	
87		if (!main_name || !sub_name || !value)
88			return 0;
89	
90		cur = disp_get_board_config(main_name, &len);
91		if (!cur || !len)
92			goto OUT;
93	
94		for (i = 0; i < len; ++i) {
95			if(!strcmp(sub_name, cur[i].name)) {
96				if (cur[i].type == PROPERTY_INTGER) {
97					*(u32 *)value = cur[i].v.value;
98				} else if (cur[i].type == PROPERTY_STRING) {
99					memcpy(value, cur[i].v.str, strlen(cur[i].v.str) + 1);
100				} else if (cur[i].type == PROPERTY_GPIO) {
101					struct disp_gpio_set_t *gpio_info =
102						(struct disp_gpio_set_t *)value;
103					gpio_info->gpio = cur[i].v.gpio_list.gpio;
104					gpio_info->mul_sel = cur[i].v.gpio_list.mul_sel;
105					gpio_info->pull = cur[i].v.gpio_list.pull;
106					gpio_info->drv_level = cur[i].v.gpio_list.drv_level;
107					gpio_info->data = cur[i].v.gpio_list.data;
108					memcpy(gpio_info->gpio_name, sub_name, strlen(sub_name) + 1);
109				} else if (cur[i].type == PROPERTY_POWER) {
110					struct disp_power_t *power =
111						(struct disp_power_t *)value;
112					memcpy(power, &cur[i].v.power, sizeof(struct disp_power_t));
113				}
114				return cur[i].type;
115			}
116		}
117	OUT:
118		return PROPERTY_UNDEFINED;
119	#endif
120	}
