122	struct disp_gpio_set_t *disp_get_all_pin_property(const char *main_name,
123						     u32 *list_len)
124	{
125		static struct disp_gpio_set_t gpio_list[MAX_PIN_NUM];
126		u32 i = 0, len = 0, j = 0;
127		struct property_t *cur = NULL;
128	#if (RTOS_SYS_CONFIG_USE == 1)
129		return NULL;
130	#else
131		memset(gpio_list, 0, 30 * sizeof(struct disp_gpio_set_t));
132	
133		if (!main_name)
134			return NULL;
135		cur = disp_get_board_config(main_name, &len);
136		if (!cur || !len)
137			return NULL;
138	
139		for (i = 0, j = 0; i < len; ++i) {
140			if (cur[i].type == PROPERTY_PIN) {
141				if (j == MAX_PIN_NUM)
142					return NULL;
143				memcpy(&gpio_list[j], &cur[i].v.gpio_list,
144				       sizeof(struct disp_gpio_set_t));
145				++j;
146			}
147		}
148	
149		*list_len = j;
150	
151		return gpio_list;
152	#endif
153	}
