17	static void lcd_cfg_panel_info(struct panel_extend_para *info){
18	
19	    syslog(LOG_INFO, "6FHD: Configuring panel info...\n");
20	
21	    if (!info) {
22	        syslog(LOG_ERR, "6FHD: ERROR - panel info pointer is NULL!\n");
23	        return;
24	    }
25	
26	    u32 i = 0, j = 0;
27	    u32 items;
28	
29	    u8 lcd_gamma_tbl[][2] = {
30			{0, 0},
31			{15, 15},
32			{30, 30},
33			{45, 45},
34			{60, 60},
35			{75, 75},
36			{90, 90},
37			{105, 105},
38			{120, 120},
39			{135, 135},
40			{150, 150},
41			{165, 165},
42			{180, 180},
43			{195, 195},
44			{210, 210},
45			{225, 225},
46			{240, 240},
47			{255, 255},
48		};
49	
50	    u32 lcd_cmap_tbl[2][3][4] = {
51	        {
52	            {LCD_CMAP_G0, LCD_CMAP_B1, LCD_CMAP_G2, LCD_CMAP_B3},
53	            {LCD_CMAP_B0, LCD_CMAP_R1, LCD_CMAP_B2, LCD_CMAP_R3},
54	            {LCD_CMAP_R0, LCD_CMAP_G1, LCD_CMAP_R2, LCD_CMAP_G3},
55	        },
56	        {
57	            {LCD_CMAP_B3, LCD_CMAP_G2, LCD_CMAP_B1, LCD_CMAP_G0},
58	            {LCD_CMAP_R3, LCD_CMAP_B2, LCD_CMAP_R1, LCD_CMAP_B0},
59	            {LCD_CMAP_G3, LCD_CMAP_R2, LCD_CMAP_G1, LCD_CMAP_R0},
60	        },
61	    };
62	    memset(info, 0, sizeof(struct panel_extend_para));
63	
64	    items = sizeof(lcd_gamma_tbl) / 2;
65	    for (i = 0; i < items - 1; i++) {
66	        u32 num = lcd_gamma_tbl[i + 1][0] - lcd_gamma_tbl[i][0];
67	
68	        for (j = 0; j < num; j++) {
69	            u32 value = 0;
70	
71	            value = lcd_gamma_tbl[i][1] +
72	                ((lcd_gamma_tbl[i + 1][1] - lcd_gamma_tbl[i][1]) * j) / num;
73	            info->lcd_gamma_tbl[lcd_gamma_tbl[i][0] + j] =
74	                (value << 16) + (value << 8) + value;
75	        }
76	    }
77	
78	    info->lcd_gamma_tbl[255] = (lcd_gamma_tbl[items - 1][1] << 16) +
79	                               (lcd_gamma_tbl[items - 1][1] << 8) +
80	                               lcd_gamma_tbl[items - 1][1];
81	
82	    memcpy(info->lcd_cmap_tbl, lcd_cmap_tbl, sizeof(lcd_cmap_tbl));
83	
84	    syslog(LOG_INFO, "6FHD: Panel configuration completed successfully\n");
85	}
