88	static s32 lcd_open_flow(u32 sel){
89	    syslog(LOG_INFO, "6FHD: Starting LCD open flow, sel=%lu\n", sel);
90	
91	    LCD_OPEN_FUNC(sel, lcd_power_on, 10);
92	    LCD_OPEN_FUNC(sel, lcd_panel_init, 10);
93	    LCD_OPEN_FUNC(sel, sunxi_lcd_tcon_enable, 50);
94	    LCD_OPEN_FUNC(sel, lcd_bl_open, 0);
95	
96	    return 0;
97	}
98	
99	/*关机时序配置*/
100	static s32 lcd_close_flow(u32 sel)
101	{
102	    syslog(LOG_INFO, "6FHD: Starting LCD close flow, sel=%lu\n", sel);
103	
104	    LCD_CLOSE_FUNC(sel, lcd_bl_close, 0);
105	    LCD_CLOSE_FUNC(sel, sunxi_lcd_tcon_disable, 0);
106	    LCD_CLOSE_FUNC(sel, lcd_panel_exit, 200);
107	    LCD_CLOSE_FUNC(sel, lcd_power_off, 500);
108	
109	    return 0;
110	}
