112	//上电时序配置
113	static void lcd_power_on(u32 sel)
114	{
115	    syslog(LOG_INFO, "6FHD: Power on sequence started\n");
116	    
117	    // 拉低复位
118	    panel_reset(sel, GPIO_DATA_LOW);
119	    sunxi_lcd_delay_ms(10);
120	    
121	    // 使能1.8V电源
122	    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC1);
123	    sunxi_lcd_delay_ms(20);
124	    
125	    // 配置引脚
126	    sunxi_lcd_pin_cfg(sel, 1);
127	    sunxi_lcd_delay_ms(50);
128	    
129	    // 释放复位 (active low, 所以拉高)
130	    panel_reset(sel, GPIO_DATA_HIGH);
131	    sunxi_lcd_delay_ms(20);
132	    
133	    syslog(LOG_INFO, "6FHD: Power-on sequence completed\n");
134	}
