136	/*下电函数*/
137	static void lcd_power_off(u32 sel)
138	{
139	    syslog(LOG_INFO, "6FHD: Power off sequence started\n");
140	    
141	    sunxi_lcd_dsi_clk_disable(sel);
142	    sunxi_lcd_delay_ms(20);
143	    
144	    panel_reset(sel, GPIO_DATA_LOW);
145	    sunxi_lcd_delay_ms(20);
146	    
147	    sunxi_lcd_pin_cfg(sel, 0);
148	    sunxi_lcd_delay_ms(20);
149	    
150	    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC1);
151	    sunxi_lcd_delay_ms(20);
152	}
