154	/*开启背光*/
155	static void lcd_bl_open(u32 sel)
156	{
157	    syslog(LOG_INFO, "6FHD: Enabling PWM backlight (PWM2)\n");
158	    sunxi_lcd_pwm_enable(sel);
159	    sunxi_lcd_delay_ms(100);
160	    
161	    sunxi_lcd_backlight_enable(sel);
162	    sunxi_lcd_delay_ms(100);
163	}
164	
165	/*关闭背光*/
166	static void lcd_bl_close(u32 sel)
167	{
168	    syslog(LOG_INFO, "6FHD: Backlight off\n");
169	    
170	    sunxi_lcd_backlight_disable(sel);
171	    sunxi_lcd_pwm_disable(sel);
172	    sunxi_lcd_delay_ms(200);
173	}
