175	static void lcd_panel_init(u32 sel)
176	{
177	    syslog(LOG_INFO, "6FHD: Panel init started\n");
178	    
179	    // Sleep Out (0x11)
180	    syslog(LOG_INFO, "6FHD: Sending EXIT_SLEEP_MODE (0x11)\n");
181	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);
182	    sunxi_lcd_delay_ms(120);
183	    
184	    // Display On (0x29)
185	    syslog(LOG_INFO, "6FHD: Sending SET_DISPLAY_ON (0x29)\n");
186	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);
187	    sunxi_lcd_delay_ms(100);
188	    
189	    syslog(LOG_INFO, "6FHD: Panel init completed\n");
190	}
191	
192	static void lcd_panel_exit(u32 sel)
193	{
194	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_ENTER_SLEEP_MODE);
195	    sunxi_lcd_delay_ms(80);
196	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_OFF);
197	    sunxi_lcd_delay_ms(50);
198	}
