676		/*clear tcon_irq_flag except FSYNC_INT_INV*/
677		lcd_dev[sel]->tcon_gint0.bits.tcon_irq_flag &= 0x00000004;
678		if ((panel->lcd_if == LCD_IF_HV) || (panel->lcd_if == LCD_IF_LVDS) ||
