684		} else if (panel->lcd_if == LCD_IF_CPU) {
685			lcd_dev[sel]->tcon0_ctl.bits.tcon0_en = 1;
686			if ((panel->lcd_cpu_mode == 0)
687			    && (panel->lcd_if == LCD_IF_CPU))
688				tcon_irq_enable(sel, LCD_IRQ_TCON0_VBLK);
689			else {
690				lcd_dev[sel]->tcon0_cpu_ctl.bits.da = 1;
691				tcon_irq_enable(sel, LCD_IRQ_TCON0_CNTR);
692			}
693		} else if (panel->lcd_if == LCD_IF_DSI) {
694			lcd_dev[sel]->tcon0_dclk.bits.tcon0_dclk_en = 0xf;
695			lcd_dev[sel]->tcon0_ctl.bits.tcon0_en = 1;
696			if (panel->lcd_dsi_if == LCD_DSI_IF_COMMAND_MODE)
697				tcon_irq_enable(sel, LCD_IRQ_TCON0_CNTR);
698	#if defined(SUPPORT_DSI) && !defined(DSI_VERSION_40)
699			else if (panel->lcd_dsi_if == LCD_DSI_IF_VIDEO_MODE ||
700				 panel->lcd_dsi_if == LCD_DSI_IF_BURST_MODE) {
701				tcon_irq_enable(sel, LCD_IRQ_TCON0_VBLK);
702				lcd_dev[sel]->tcon0_dclk.bits.tcon0_dclk_en = 0xf;
703			}
704	#endif
705			else
706				lcd_dev[sel]->tcon0_dclk.bits.tcon0_dclk_en = 0xf;
707		}
708	
