1291	u16 dsi_crc_pro(u8 *pd_p, u32 pd_bytes)
1292	{
1293		u16 gen_code = 0x8408;
1294		u16 byte_cntr;
1295		u8 bit_cntr;
1296		u8 curr_data;
1297		u16 crc = 0xffff;
1298	
1299		if (pd_bytes > 0) {
1300			for (byte_cntr = 0; byte_cntr < pd_bytes; byte_cntr++) {
1301				curr_data = *(pd_p + byte_cntr);
1302				for (bit_cntr = 0; bit_cntr < 8; bit_cntr++) {
1303					if (((crc & 0x0001) ^
1304					     ((0x0001 * curr_data) & 0x0001)) > 0)
1305						crc = ((crc >> 1) & 0x7fff) ^ gen_code;
1306					else
1307						crc = (crc >> 1) & 0x7fff;
1308					curr_data = (curr_data >> 1) & 0x7f;
1309				}
1310			}
1311		}
1312		return crc;
1313	}
