1322	
1323		if (pd_bytes > 0) {
1324			for (byte_cntr = 0; byte_cntr < pd_bytes; byte_cntr++) {
1325				curr_data = pd;
1326				for (bit_cntr = 0; bit_cntr < 8; bit_cntr++) {
