1328					     ((0x0001 * curr_data) & 0x0001)) > 0)
1329						crc = ((crc >> 1) & 0x7fff) ^ gen_code;
1330					else
1331						crc = (crc >> 1) & 0x7fff;
1332					curr_data = (curr_data >> 1) & 0x7f;
1333				}
1334			}
1335		}
