695		    { 24, 24, 18, 16 }, { 24, 24, 16, 0 }, { 24, 24, 18, 16 } };
696	
697		frq = dclk * pixel_bits[mode][format] / lane * 1000000; /* unit:Hz */
698	
699		frq_p = frq;
700		for (m = 0; frq_p <= vco;) {
701			m++;
702			frq_p = frq * m;
703		}
704	
705		n = div_const(frq_p, 24000000);
706		if (m > 4) {
707			syslog(LOG_ERR,"pclk is too small\n");
708		/* To get the desired hs frequency while meeting the VCO, increase pclk */
709			m = 4;
710		}
711		if (m)
712			div_m0 = m - 1;
713	
714		dphy_dev[sel]->dphy_pll_reg0.bits.n =
715		    n; /* HS_clk:24MHz*n/(p+1)/(m0+1); */
716		       /* LP_clk_src:24MHz*n/(p+1)/(m0+1)/(m1+1) */
717		dphy_dev[sel]->dphy_pll_reg0.bits.p = div_p;
718		dphy_dev[sel]->dphy_pll_reg0.bits.m0 = div_m0;
719		dphy_dev[sel]->dphy_pll_reg0.bits.m1 = 2; /*?? */
720		dphy_dev[sel]->dphy_pll_reg2.dwval = 0; /*Disable sdm*/
721	
722		return 24000000 * n / (div_p + 1) / (div_m0 + 1);
723	}
