136	s32 dsi_start(u32 sel, enum __dsi_start_t func)
137	{
138		switch (func) {
139		case DSI_START_TBA:
140			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
141			    DSI_INST_ID_TBA << (4 * DSI_INST_ID_LP11)
142			    | DSI_INST_ID_END << (4 * DSI_INST_ID_TBA);
143			break;
144		case DSI_START_HSTX:
145			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
146			    DSI_INST_ID_HSC << (4 * DSI_INST_ID_LP11)
147			    | DSI_INST_ID_NOP << (4 * DSI_INST_ID_HSC)
148			    | DSI_INST_ID_HSD << (4 * DSI_INST_ID_NOP)
149			    | DSI_INST_ID_DLY << (4 * DSI_INST_ID_HSD)
150			    | DSI_INST_ID_NOP << (4 * DSI_INST_ID_DLY)
151			    | DSI_INST_ID_END << (4 * DSI_INST_ID_HSCEXIT);
152			break;
153		case DSI_START_LPTX:
154			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
155			    DSI_INST_ID_LPDT << (4 * DSI_INST_ID_LP11)
156			    | DSI_INST_ID_END << (4 * DSI_INST_ID_LPDT);
157			break;
158		case DSI_START_LPRX:
159			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
160			    DSI_INST_ID_LPDT << (4 * DSI_INST_ID_LP11)
161			    | DSI_INST_ID_DLY << (4 * DSI_INST_ID_LPDT)
162			    | DSI_INST_ID_TBA << (4 * DSI_INST_ID_DLY)
163			    | DSI_INST_ID_END << (4 * DSI_INST_ID_TBA);
164			break;
165		case DSI_START_HSC:
166			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
167			    DSI_INST_ID_HSC << (4 * DSI_INST_ID_LP11)
168			    | DSI_INST_ID_END << (4 * DSI_INST_ID_HSC);
169			break;
170		case DSI_START_HSD:
171			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
172			    DSI_INST_ID_NOP << (4 * DSI_INST_ID_LP11)
173			    | DSI_INST_ID_HSD << (4 * DSI_INST_ID_NOP)
174			    | DSI_INST_ID_DLY << (4 * DSI_INST_ID_HSD)
175			    | DSI_INST_ID_NOP << (4 * DSI_INST_ID_DLY)
176			    | DSI_INST_ID_END << (4 * DSI_INST_ID_HSCEXIT);
177			break;
178		default:
179			dsi_dev[sel]->dsi_inst_jump_sel.dwval =
180			    DSI_INST_ID_END << (4 * DSI_INST_ID_LP11);
181			break;
182		}
183		dsi_dev[sel]->dsi_basic_ctl0.bits.inst_st = 0;
184		dsi_dev[sel]->dsi_basic_ctl0.bits.inst_st = 1;
185		if (func == DSI_START_HSC)
186			dsi_dev[sel]->dsi_inst_func[DSI_INST_ID_LP11].bits.lane_cen =
187			    (dsi_dev[sel]->dsi_pixel_ctl0.bits.pd_plug_dis) ? 0 : 1;
188	
189		return 0;
190	}
