228	static void lcd_panel_init(u32 sel)
229	{
230	    struct ek79007ad2_config chip_config;
231	    // 获取EK79007AD2芯片级配置
232	    if(get_ek79007ad2_config(sel, &chip_config) != 0) {
233	        syslog(LOG_ERR, "fisker T070S140B: Failed to get chip config!\n");
234	        return;
235	    }
236	
237	    // R01h - 软件复位
238	    syslog(LOG_INFO, "fisker T070S140B: Sending software reset command (0x01)\n");
239	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SOFT_RESET);
240	    sunxi_lcd_delay_ms(120);
241	
242	    // R11h - EXIT_SLEEP_MODE
243	    syslog(LOG_INFO, "fisker T070S140B: Sending EXIT_SLEEP_MODE (0x11) - vendor mandatory\n");
244	    printf("[FISKER T070S140B] Sending EXIT_SLEEP_MODE command (0x11)\n");
245	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);
246	
247	    sunxi_lcd_delay_ms(30);
248	      sunxi_lcd_dsi_gen_write_1para(sel, 0xB0, chip_config.power_enable);
249	    sunxi_lcd_delay_ms(10);
250	        sunxi_lcd_dsi_gen_write_1para(sel, 0xB1, chip_config.res_config);
251	    sunxi_lcd_delay_ms(10);
252	
253	    // RB2h - Lane控制
254	    syslog(LOG_INFO, "fisker T070S140B: Setting Lane config (0xB2) = 0x30 (4-lane MIPI)\n");
255	    sunxi_lcd_dsi_gen_write_1para(sel, 0xB2, 0x30);
256	    sunxi_lcd_delay_ms(10);
257	
258	    // Gamma校正电压设置 (R80h~R86h)
259	    syslog(LOG_INFO, "fisker T070S140B: Setting Gamma correction registers (vendor mandatory)\n");
260	    printf("[FISKER T070S140B] Setting Gamma correction registers\n");
261	    sunxi_lcd_dsi_gen_write_1para(sel, 0x80, 0xAC);
262	    sunxi_lcd_dsi_gen_write_1para(sel, 0x81, 0xB8);
263	    sunxi_lcd_dsi_gen_write_1para(sel, 0x82, 0x09);
264	    sunxi_lcd_dsi_gen_write_1para(sel, 0x83, 0x78);
265	    sunxi_lcd_dsi_gen_write_1para(sel, 0x84, 0x7F);
266	    sunxi_lcd_dsi_gen_write_1para(sel, 0x85, 0xBB);
267	    sunxi_lcd_dsi_gen_write_1para(sel, 0x86, 0x70);
268	    // R29h - Display On
269	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);
270	    sunxi_lcd_delay_ms(200);
271	}
