273	static void lcd_panel_exit(u32 sel)
274	{
275	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_ENTER_SLEEP_MODE); // Sleep In
276	    sunxi_lcd_delay_ms(80);
277	    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_OFF); // Display Off
278	    sunxi_lcd_delay_ms(50);
279	}
