/* 6FHD LCD0 配置参数
 * 分辨率: 1080x2160
 * DSI Lanes: 4
 * 像素格式: RGB888
 * 时钟频率: 145MHz (从RK3566设备树迁移)
 * DSI模式: Video Burst
 *
 * 时序 (从RK3566设备树迁移):
 *   hactive=1080, vactive=2160
 *   hfp=60, hbp=30, hsync-len=10
 *   vfp=10, vbp=10, vsync-len=2
 *
 * 引脚 (沿用7英寸gemini-s1的MIPI引脚分配):
 *   DSI数据/时钟: PD0-PD9 (4 lanes + clock)
 *   屏幕复位: PD19 (lcd_gpio_0)
 *   PWM背光: PD20 (PWM CH4)
 *   触摸I2C: PB2(SDA) / PB3(SCL) — 保留
 *   PB4: 从触摸RST改为5V LDO EN → 1.8V VCCCIO
 */

struct property_t g_lcd0_config[] = {
    // 基本LCD参数配置
    {
        .name = "lcd_used",
        .type = PROPERTY_INTGER,
        .v.value = 1,  // 使能LCD0
    },
    {
        .name = "lcd_driver_name",
        .type = PROPERTY_STRING,
        .v.str = "mipi_6fhd",
    },
    {
        .name = "lcd_if",
        .type = PROPERTY_INTGER,
        .v.value = 4,  // 4=DSI接口
    },
    // 分辨率配置 (6FHD 1080x2160)
    {
        .name = "lcd_x",
        .type = PROPERTY_INTGER,
        .v.value = 1080,
    },
    {
        .name = "lcd_y",
        .type = PROPERTY_INTGER,
        .v.value = 2160,
    },
    {
        .name = "lcd_width",
        .type = PROPERTY_INTGER,
        .v.value = 74,   // 物理宽度74mm
    },
    {
        .name = "lcd_height",
        .type = PROPERTY_INTGER,
        .v.value = 133,  // 物理高度133mm
    },
    {
        .name = "lcd_dclk_freq",
        .type = PROPERTY_INTGER,
        .v.value = 145,  // 145MHz (从RK3566迁移)
    },
    // MIPI DSI配置 — Burst Mode (匹配RK3566 dtsi: VIDEO|VIDEO_BURST)
    {
        .name = "lcd_dsi_if",
        .type = PROPERTY_INTGER,
        .v.value = LCD_DSI_IF_BURST_MODE,  // 2=Burst模式
    },
    {
        .name = "lcd_dsi_lane",
        .type = PROPERTY_INTGER,
        .v.value = 4,
    },
    {
        .name = "lcd_dsi_format",
        .type = PROPERTY_INTGER,
        .v.value = 0,     // 0=RGB888格式
    },
    {
        .name = "lcd_dsi_te",
        .type = PROPERTY_INTGER,
        .v.value = 0,     // 不使用TE信号
    },
    {
        .name = "lcd_dsi_port_num",
        .type = PROPERTY_INTGER,
        .v.value = 3,     // DSI端口0
    },
    {
        .name = "lcd_dsi_clk_rate",
        .type = PROPERTY_INTGER,
        .v.value = 870,   // 145MHz * 24bpp / 4lanes = 870Mbps
    },
    // 时序配置 (从RK3566设备树迁移)
    // hactive=1080, hfp=60, hbp=30, hsync-len=10 → HT=1180
    {
        .name = "lcd_ht",
        .type = PROPERTY_INTGER,
        .v.value = 1180,  // 水平总计 (1080+60+30+10=1180)
