    {
        .name = "lcd_hbp",
        .type = PROPERTY_INTGER,
        .v.value = 30,    // 水平后肩 (RK3566: hback-porch=30)
    },
    {
        .name = "lcd_hfp",
        .type = PROPERTY_INTGER,
        .v.value = 60,    // 水平前肩 (RK3566: hfront-porch=60)
    },
    {
        .name = "lcd_hspw",
        .type = PROPERTY_INTGER,
        .v.value = 10,    // 水平同步脉宽 (RK3566: hsync-len=10)
