    // vactive=2160, vfp=10, vbp=10, vsync-len=2 → VT=2182
    {
        .name = "lcd_vt",
        .type = PROPERTY_INTGER,
        .v.value = 2182,  // 垂直总计 (2160+10+10+2=2182)
    },
    {
        .name = "lcd_vbp",
        .type = PROPERTY_INTGER,
        .v.value = 10,    // 垂直后肩 (RK3566: vback-porch=10)
    },
    {
        .name = "lcd_vfp",
        .type = PROPERTY_INTGER,
        .v.value = 10,    // 垂直前肩 (RK3566: vfront-porch=10)
    },
    {
        .name = "lcd_vspw",
        .type = PROPERTY_INTGER,
        .v.value = 2,     // 垂直同步脉宽 (RK3566: vsync-len=2)
