extern s32 bsp_disp_lcd_set_bright(u32 disp, u32 bright);

static void lcd_power_on(u32 sel);
static void lcd_power_off(u32 sel);
static void lcd_bl_open(u32 sel);
static void lcd_bl_close(u32 sel);
static void lcd_panel_init(u32 sel);
static void lcd_panel_exit(u32 sel);

// 复位控制 (GPIOD_PD19, active low)
#define panel_reset(sel, val) sunxi_lcd_gpio_set_value(sel, 0, val)

static void lcd_cfg_panel_info(struct panel_extend_para *info)
{
    syslog(LOG_INFO, "6FHD: Configuring panel info...\n");

    if (!info) {
        syslog(LOG_ERR, "6FHD: ERROR - panel info pointer is NULL!\n");
        return;
    }

    u32 i = 0, j = 0;
    u32 items;

    u8 lcd_gamma_tbl[][2] = {
        {0, 0},   {15, 15},  {30, 30},  {45, 45},
        {60, 60}, {75, 75},  {90, 90},  {105, 105},
        {120, 120}, {135, 135}, {150, 150}, {165, 165},
        {180, 180}, {195, 195}, {210, 210}, {225, 225},
        {240, 240}, {255, 255},
    };

    u32 lcd_cmap_tbl[2][3][4] = {
        {
            {LCD_CMAP_G0, LCD_CMAP_B1, LCD_CMAP_G2, LCD_CMAP_B3},
            {LCD_CMAP_B0, LCD_CMAP_R1, LCD_CMAP_B2, LCD_CMAP_R3},
            {LCD_CMAP_R0, LCD_CMAP_G1, LCD_CMAP_R2, LCD_CMAP_G3},
        },
        {
            {LCD_CMAP_B3, LCD_CMAP_G2, LCD_CMAP_B1, LCD_CMAP_G0},
            {LCD_CMAP_R3, LCD_CMAP_B2, LCD_CMAP_R1, LCD_CMAP_B0},
            {LCD_CMAP_G3, LCD_CMAP_R2, LCD_CMAP_G1, LCD_CMAP_R0},
        },
    };

    memset(info, 0, sizeof(struct panel_extend_para));

    items = sizeof(lcd_gamma_tbl) / 2;
    for (i = 0; i < items - 1; i++) {
        u32 num = lcd_gamma_tbl[i + 1][0] - lcd_gamma_tbl[i][0];
        for (j = 0; j < num; j++) {
            u32 value = 0;
            value = lcd_gamma_tbl[i][1] +
                ((lcd_gamma_tbl[i + 1][1] - lcd_gamma_tbl[i][1]) * j) / num;
            info->lcd_gamma_tbl[lcd_gamma_tbl[i][0] + j] =
                (value << 16) + (value << 8) + value;
        }
    }
    info->lcd_gamma_tbl[255] = (lcd_gamma_tbl[items - 1][1] << 16) +
                               (lcd_gamma_tbl[items - 1][1] << 8) +
                               lcd_gamma_tbl[items - 1][1];

    memcpy(info->lcd_cmap_tbl, lcd_cmap_tbl, sizeof(lcd_cmap_tbl));

    syslog(LOG_INFO, "6FHD: Panel configuration completed successfully\n");
}

/* 开机时序配置 */
static s32 lcd_open_flow(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Starting LCD open flow, sel=%lu\n", sel);

    LCD_OPEN_FUNC(sel, lcd_power_on, 10);
    LCD_OPEN_FUNC(sel, lcd_panel_init, 10);
    LCD_OPEN_FUNC(sel, sunxi_lcd_tcon_enable, 50);
    LCD_OPEN_FUNC(sel, lcd_bl_open, 0);

    return 0;
}

/* 关机时序配置 */
static s32 lcd_close_flow(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Starting LCD close flow, sel=%lu\n", sel);

    LCD_CLOSE_FUNC(sel, lcd_bl_close, 0);
    LCD_CLOSE_FUNC(sel, sunxi_lcd_tcon_disable, 0);
    LCD_CLOSE_FUNC(sel, lcd_panel_exit, 200);
    LCD_CLOSE_FUNC(sel, lcd_power_off, 500);

    return 0;
}

/* 上电时序配置 */
static void lcd_power_on(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Power on sequence started\n");

    /* 确保复位低电平 */
    panel_reset(sel, GPIO_DATA_LOW);
    sunxi_lcd_delay_ms(10);

    /* 使能1.8V电源 */
    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC1);
    sunxi_lcd_delay_ms(10);
    sunxi_lcd_power_enable(sel, AXP2101_ID_DCDC3);
    sunxi_lcd_delay_ms(20);

    /* 配置引脚 */
    sunxi_lcd_pin_cfg(sel, 1);
    sunxi_lcd_delay_ms(50);

    /* 释放复位 */
    panel_reset(sel, GPIO_DATA_HIGH);
    sunxi_lcd_delay_ms(120);  /* RK3566: reset-delay-ms = 120 */

    syslog(LOG_INFO, "6FHD: Power-on sequence completed\n");
}

/* 下电函数 */
static void lcd_power_off(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Power off sequence started\n");

    sunxi_lcd_dsi_clk_disable(sel);
    sunxi_lcd_delay_ms(20);

    panel_reset(sel, GPIO_DATA_LOW);
    sunxi_lcd_delay_ms(20);

    sunxi_lcd_pin_cfg(sel, 0);
    sunxi_lcd_delay_ms(20);

    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC3);
    sunxi_lcd_power_disable(sel, AXP2101_ID_DCDC1);
    sunxi_lcd_delay_ms(20);
}

/* 开启背光 */
static void lcd_bl_open(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Enabling PWM backlight\n");
    sunxi_lcd_pwm_enable(sel);
    sunxi_lcd_delay_ms(100);

    sunxi_lcd_backlight_enable(sel);
    sunxi_lcd_delay_ms(100);
}

/* 关闭背光 */
static void lcd_bl_close(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Backlight off\n");

    sunxi_lcd_backlight_disable(sel);
    sunxi_lcd_pwm_disable(sel);
    sunxi_lcd_delay_ms(200);
}

/* Panel初始化 — 从RK3566 dtsi迁移 */
static void lcd_panel_init(u32 sel)
{
    syslog(LOG_INFO, "6FHD: Panel init started\n");

    /* Sleep Out (0x11) — RK3566: 05 78 01 11 (delay 120ms) */
    syslog(LOG_INFO, "6FHD: Sending EXIT_SLEEP_MODE (0x11)\n");
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);
    sunxi_lcd_delay_ms(120);

    /* Display On (0x29) — RK3566: 05 05 01 29 (delay 5ms) */
    syslog(LOG_INFO, "6FHD: Sending SET_DISPLAY_ON (0x29)\n");
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);
    sunxi_lcd_delay_ms(50);

    syslog(LOG_INFO, "6FHD: Panel init completed\n");
}

static void lcd_panel_exit(u32 sel)
{
    /* Display Off (0x28) — RK3566 panel-exit-sequence */
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_OFF);
    sunxi_lcd_delay_ms(50);

    /* Sleep In (0x10) — RK3566 panel-exit-sequence */
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_ENTER_SLEEP_MODE);
    sunxi_lcd_delay_ms(80);
}

/* 用户自定义函数 */
static s32 lcd_user_defined_func(u32 sel, u32 para1, u32 para2, u32 para3)
{
    bsp_disp_lcd_set_bright(sel, 200);
    return 0;
}

struct __lcd_panel mipi_6fhd_panel = {
    .name = "mipi_6fhd",
    .func = {
        .cfg_panel_info =  lcd_cfg_panel_info,
        .cfg_open_flow  =  lcd_open_flow,
        .cfg_close_flow =  lcd_close_flow,
        .lcd_user_defined_func = lcd_user_defined_func,
    },
};

