27	 ****************************************************************************/
28	
29	/* SEC TS I2C Configuration */
30	
31	#define SEC_TS_I2C_ADDR       0x48
32	#define SEC_TS_I2C_FREQ       400000  /* 400kHz */
33	
34	/* SEC TS Registers */
35	
36	#define SEC_TS_CMD_WAKEUP     0x00
37	#define SEC_TS_CMD_SW_RESET   0x01
38	#define SEC_TS_CMD_READ_ONE   0x02
39	#define SEC_TS_CMD_READ_ALL   0x03
40	#define SEC_TS_CMD_WRITE      0x04
41	#define SEC_TS_CMD_NOTIFY     0x05
42	
43	/* Touch point structure */
44	
45	#define SEC_TS_MAX_TOUCH      10
46	#define SEC_TS_BUFFER_SIZE    64
47	
48	/* Work queue configuration */
49	
50	#define SEC_TS_WORK_DELAY     MSEC2TICK(10)  /* 10ms polling */
51	
52	/****************************************************************************
53	 * Private Types
54	 ****************************************************************************/
55	
56	/* Touch point data */
57	
58	struct sec_ts_touchpoint_s
59	{
60	  uint8_t  id;
61	  uint16_t x;
62	  uint16_t y;
