68	
69	struct sec_ts_dev_s
70	{
71	  struct touch_lowerhalf_s  touch_lower;
72	  
73	  struct i2c_master_s      *i2c;
74	  struct work_s             work;
75	  mutex_t                   lock;
76	  
77	  uint16_t                  max_x;
78	  uint16_t                  max_y;
79	  
80	  uint8_t                   buffer[SEC_TS_BUFFER_SIZE];
81	  struct sec_ts_touchpoint_s points[SEC_TS_MAX_TOUCH];
82	  
