91	static int  sec_ts_i2c_read(struct sec_ts_dev_s *dev, uint8_t cmd,
92	                            uint8_t *buf, int len);
93	static int  sec_ts_i2c_write(struct sec_ts_dev_s *dev, uint8_t cmd,
94	                             const uint8_t *buf, int len);
95	static int  sec_ts_sw_reset(struct sec_ts_dev_s *dev);
96	static int  sec_ts_init(struct sec_ts_dev_s *dev);
