110	
111	/****************************************************************************
112	 * Name: sec_ts_i2c_read
113	 *
114	 * Description:
115	 *   Read data from SEC TS via I2C
116	 *
117	 ****************************************************************************/
118	
119	static int sec_ts_i2c_read(struct sec_ts_dev_s *dev, uint8_t cmd,
120	                           uint8_t *buf, int len)
121	{
122	  struct i2c_msg_s msg[2];
123	  int ret;
124	
125	  /* Send command byte */
126	
127	  msg[0].frequency = SEC_TS_I2C_FREQ;
128	  msg[0].addr      = SEC_TS_I2C_ADDR;
129	  msg[0].flags     = 0;
130	  msg[0].buffer    = &cmd;
131	  msg[0].length    = 1;
132	
133	  /* Read data */
134	
135	  msg[1].frequency = SEC_TS_I2C_FREQ;
136	  msg[1].addr      = SEC_TS_I2C_ADDR;
137	  msg[1].flags     = I2C_M_READ;
138	  msg[1].buffer    = buf;
139	  msg[1].length    = len;
140	
141	  ret = I2C_TRANSFER(dev->i2c, msg, 2);
142	  if (ret < 0)
143	    {
144	      ierr("SEC TS I2C read failed: %d\n", ret);
145	      return ret;
146	    }
147	
148	  return 0;
149	}
150	
151	/****************************************************************************
152	 * Name: sec_ts_i2c_write
153	 *
154	 * Description:
155	 *   Write data to SEC TS via I2C
156	 *
157	 ****************************************************************************/
158	
159	static int sec_ts_i2c_write(struct sec_ts_dev_s *dev, uint8_t cmd,
160	                            const uint8_t *buf, int len)
161	{
162	  struct i2c_msg_s msg;
163	  uint8_t *wbuf;
164	  int ret;
165	  int i;
166	
167	  /* Allocate buffer for command + data */
168	
169	  wbuf = kmm_malloc(len + 1);
170	  if (wbuf == NULL)
171	    {
172	      return -ENOMEM;
173	    }
174	
175	  wbuf[0] = cmd;
176	  for (i = 0; i < len; i++)
177	    {
178	      wbuf[i + 1] = buf[i];
179	    }
180	
181	  msg.frequency = SEC_TS_I2C_FREQ;
182	  msg.addr      = SEC_TS_I2C_ADDR;
183	  msg.flags     = 0;
184	  msg.buffer    = wbuf;
185	  msg.length    = len + 1;
186	
187	  ret = I2C_TRANSFER(dev->i2c, &msg, 1);
188	
189	  kmm_free(wbuf);
190	
191	  if (ret < 0)
192	    {
193	      ierr("SEC TS I2C write failed: %d\n", ret);
194	    }
195	
196	  return ret;
197	}
198	
199	/****************************************************************************
200	 * Name: sec_ts_sw_reset
201	 *
202	 * Description:
203	 *   Perform software reset on SEC TS
204	 *
205	 ****************************************************************************/
206	
207	static int sec_ts_sw_reset(struct sec_ts_dev_s *dev)
208	{
209	  uint8_t cmd = SEC_TS_CMD_SW_RESET;
210	  int ret;
211	
212	  ret = sec_ts_i2c_write(dev, cmd, NULL, 0);
213	  if (ret < 0)
214	    {
215	      return ret;
216	    }
217	
218	  /* Wait for reset */
219	
220	  nxsig_usleep(50000);  /* 50ms */
221	
222	  return 0;
223	}
224	
225	/****************************************************************************
226	 * Name: sec_ts_init
227	 *
228	 * Description:
229	 *   Initialize SEC TS controller
230	 *
231	 ****************************************************************************/
232	
233	static int sec_ts_init(struct sec_ts_dev_s *dev)
234	{
235	  uint8_t buf[4];
236	  int ret;
237	
238	  /* Read chip ID to verify communication */
239	
240	  ret = sec_ts_i2c_read(dev, 0x00, buf, 4);
241	  if (ret < 0)
242	    {
243	      ierr("SEC TS: Failed to read chip ID\n");
244	      return ret;
245	    }
246	
247	  iinfo("SEC TS: Chip ID = %02x %02x %02x %02x\n",
248	        buf[0], buf[1], buf[2], buf[3]);
249	
250	  /* Software reset */
251	
252	  ret = sec_ts_sw_reset(dev);
253	  if (ret < 0)
254	    {
255	      ierr("SEC TS: Software reset failed\n");
256	      return ret;
257	    }
258	
259	  /* Set touch report mode */
260	
261	  buf[0] = 0x01;  /* Enable touch report */
262	  ret = sec_ts_i2c_write(dev, SEC_TS_CMD_WRITE, buf, 1);
263	  if (ret < 0)
264	    {
265	      ierr("SEC TS: Failed to set report mode\n");
266	      return ret;
267	    }
268	
269	  dev->initialized = true;
270	  iinfo("SEC TS: Initialization complete\n");
271	
272	  return 0;
273	}
274	
275	/****************************************************************************
276	 * Name: sec_ts_process_touch
277	 *
278	 * Description:
279	 *   Process touch data from SEC TS
280	 *
281	 ****************************************************************************/
282	
283	static void sec_ts_process_touch(struct sec_ts_dev_s *dev)
284	{
285	  struct touch_point_s point;
286	  int ret;
287	  int i;
288	  uint8_t num_points;
289	
290	  /* Read touch data */
291	
292	  ret = sec_ts_i2c_read(dev, SEC_TS_CMD_READ_ALL, dev->buffer,
293	                        SEC_TS_BUFFER_SIZE);
294	  if (ret < 0)
295	    {
296	      ierr("SEC TS: Failed to read touch data\n");
297	      return;
298	    }
299	
300	  /* Parse touch points */
301	
302	  num_points = dev->buffer[0] & 0x0f;
303	  if (num_points > SEC_TS_MAX_TOUCH)
304	    {
305	      num_points = SEC_TS_MAX_TOUCH;
