312	      dev->points[i].id       = data[0];
313	      dev->points[i].x        = (data[1] << 8) | data[2];
314	      dev->points[i].y        = (data[3] << 8) | data[4];
315	      dev->points[i].pressure = data[5];
316	
317	      /* Report touch point */
318	
319	      memset(&point, 0, sizeof(point));
320	      point.x        = dev->points[i].x;
