331	    }
332	
333	  /* Report touch up if no points */
334	
335	  if (num_points == 0)
336	    {
337	      memset(&point, 0, sizeof(point));
338	      point.flags = TOUCH_UP;
339	      touch_event(dev->touch_lower.priv, &point);
340	    }
