350	
351	static void sec_ts_worker(void *arg)
352	{
353	  struct sec_ts_dev_s *dev = (struct sec_ts_dev_s *)arg;
354	  int ret;
355	
356	  if (dev->suspended)
357	    {
358	      return;
359	    }
360	
361	  /* Acquire lock */
362	
363	  ret = nxmutex_lock(&dev->lock);
364	  if (ret < 0)
365	    {
366	      return;
367	    }
368	
369	  /* Process touch data */
370	
371	  sec_ts_process_touch(dev);
372	
373	  /* Release lock */
374	
375	  nxmutex_unlock(&dev->lock);
376	
377	  /* Schedule next poll */
378	
379	  work_queue(HPWORK, &dev->work, sec_ts_worker, dev,
380	             SEC_TS_WORK_DELAY);
381	}
