+					} else if (coordinate.action == SEC_TS_Coordinate_Action_Move) {
+#ifdef CONFIG_TOUCHSCREN_SEC_TS_GLOVEMODE
+						if ((coordinate.ttype == SEC_TS_TOUCHTYPE_GLOVE) &&
