+			}
+
+			is_event_remain = 1;
+			break;
+
+		case SEC_TS_Gesture_Event:
+#ifdef SEC_TS_WAKEUP_GESTURE
+			p_event_status = (struct sec_ts_event_status *)read_event_buff;
+
+			if ((p_event_status->eid == 0x02) && (p_event_status->tchsta == 0x01)) {
