/****************************************************************************
 * boards/r528/r528s3-6fhd/src/sec_ts.c
 *
 * Samsung SEC TS Touchscreen Driver for NuttX
 *
 * Ported from Linux sec_ts driver for NuttX RTOS touch framework.
 *
 * Core changes from Linux:
 * - Linux input_dev → NuttX touch_lowerhalf_s + touch_event()
 * - Linux threaded IRQ → work_queue polling (10ms)
 * - Linux device tree → hardcoded params via sec_ts_initialize()
 * - Linux mutex → nxmutex
 *
 * Hardware: Samsung SEC TS I2C touch controller (SEC_TS_READ_ONE_EVENT 0x71)
 * Connected via I2C0 (PB2=SDA, PB3=SCL) @ 400kHz, addr 0x48
 *
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/i2c/i2c_master.h>
#include <nuttx/input/touchscreen.h>
#include <nuttx/wqueue.h>
#include <nuttx/clock.h>
#include <nuttx/kmalloc.h>
#include <nuttx/mutex.h>
#include <syslog.h>
#include <errno.h>
#include <debug.h>
#include <string.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* I2C Configuration */

#define SEC_TS_I2C_ADDR           0x48
#define SEC_TS_I2C_FREQ           400000

/* I2C retry */

#define SEC_TS_I2C_RETRY_CNT      3

/* SEC TS Register Map (from Linux driver) */

#define SEC_TS_READ_ONE_EVENT     0x71   /* Read 8-byte touch event */
#define SEC_TS_READ_DEVICE_ID     0x52   /* Read chip ID (4 bytes) */
#define SEC_TS_READ_FW_STATUS     0x51   /* Read firmware status */
#define SEC_TS_READ_FW_VERSION    0xA3   /* Read firmware version (4 bytes) */
#define SEC_TS_READ_TS_STATUS     0x70   /* Read touch status */
#define SEC_TS_READ_SUB_ID        0x53   /* Read sub ID */

#define SEC_TS_CMD_SW_RESET       0x42   /* Software reset */
#define SEC_TS_CMD_SENSE_ON       0x40   /* Enable sensing */
#define SEC_TS_CMD_STATEMANAGE_ON 0x48   /* Enable state management */
#define SEC_TS_CMD_SET_TOUCHFUNCTION 0x63 /* Set touch function */
#define SEC_TS_CMD_CLEAR_EVENT_STACK 0x60 /* Clear event queue */

/* Touch function bits */

#define SEC_TS_BIT_SETFUNC_TOUCH  (1 << 0)
#define SEC_TS_BIT_SETFUNC_HOVER  (1 << 1)
#define SEC_TS_BIT_SETFUNC_GLOVE  (1 << 3)

/* Event types (from byte[0] >> 6) */

#define SEC_TS_STATUS_EVENT       0
#define SEC_TS_COORDINATE_EVENT   1
#define SEC_TS_GESTURE_EVENT      2

/* Coordinate event actions */

#define SEC_TS_ACTION_NONE        0
#define SEC_TS_ACTION_PRESS       1
#define SEC_TS_ACTION_MOVE        2
#define SEC_TS_ACTION_RELEASE     3

/* Touch types */

#define SEC_TS_TOUCHTYPE_NORMAL   0
#define SEC_TS_TOUCHTYPE_PALM     6

/* Event buffer */

#define SEC_TS_EVENT_SIZE         8
#define MAX_SUPPORT_TOUCH_COUNT   10
#define MAX_EVENT_COUNT           100

/* Work queue polling interval */

#define SEC_TS_POLL_DELAY         MSEC2TICK(10)  /* 10ms */

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Parsed touch coordinate (aligned with Linux driver event format) */

struct sec_ts_coordinate_s
{
  uint8_t  id;          /* Touch ID (0..9) */
  uint8_t  action;      /* SEC_TS_ACTION_PRESS/MOVE/RELEASE */
  uint16_t x;           /* X coordinate (12-bit, 0..4095) */
  uint16_t y;           /* Y coordinate (12-bit, 0..4095) */
  uint8_t  z;           /* Touch width/pressure */
  uint8_t  ttype;       /* Touch type */
};

/* SEC TS device private data */

struct sec_ts_dev_s
{
  struct touch_lowerhalf_s  touch_lower;   /* NuttX touch lower-half */
  struct i2c_master_s      *i2c;           /* I2C bus */
  struct work_s             work;          /* Work queue polling */
  mutex_t                   lock;          /* Device lock */

  uint16_t                  max_x;         /* Max X resolution */
  uint16_t                  max_y;         /* Max Y resolution */
  uint8_t                   event_buf[SEC_TS_EVENT_SIZE]; /* Event read buffer */
  struct sec_ts_coordinate_s coord[MAX_SUPPORT_TOUCH_COUNT]; /* Touch states */
  int                       touch_count;   /* Active touch count */
  bool                      initialized;   /* Init done flag */
  bool                      suspended;     /* Suspend flag */
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int  sec_ts_i2c_read(struct sec_ts_dev_s *dev, uint8_t reg,
                             uint8_t *buf, int len);
static int  sec_ts_i2c_write(struct sec_ts_dev_s *dev, uint8_t reg,
                              const uint8_t *buf, int len);
static int  sec_ts_sw_reset(struct sec_ts_dev_s *dev);
static int  sec_ts_sense_on(struct sec_ts_dev_s *dev);
static int  sec_ts_init_hw(struct sec_ts_dev_s *dev);
static void sec_ts_release_all_finger(struct sec_ts_dev_s *dev);
static void sec_ts_read_event(struct sec_ts_dev_s *dev);
static void sec_ts_worker(void *arg);
static int  sec_ts_register_dev(struct sec_ts_dev_s *dev);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct sec_ts_dev_s g_sec_ts_dev;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sec_ts_i2c_read
 *
 * Description:
 *   Write register address, then read data via I2C (combined transaction).
 *
 ****************************************************************************/

static int sec_ts_i2c_read(struct sec_ts_dev_s *dev, uint8_t reg,
                            uint8_t *buf, int len)
{
  struct i2c_msg_s msg[2];
  int ret;
  int retry;

  msg[0].frequency = SEC_TS_I2C_FREQ;
  msg[0].addr      = SEC_TS_I2C_ADDR;
  msg[0].flags     = 0;               /* write */
  msg[0].buffer    = &reg;
  msg[0].length    = 1;

  msg[1].frequency = SEC_TS_I2C_FREQ;
  msg[1].addr      = SEC_TS_I2C_ADDR;
  msg[1].flags     = I2C_M_READ;      /* read */
  msg[1].buffer    = buf;
  msg[1].length    = len;

  for (retry = 0; retry < SEC_TS_I2C_RETRY_CNT; retry++)
    {
      ret = I2C_TRANSFER(dev->i2c, msg, 2);
      if (ret == OK)
        {
          return OK;
        }

      nxsig_usleep(1000);
    }

  ierr("SEC TS: I2C read reg 0x%02x failed: %d\n", reg, ret);
  return -EIO;
}

/****************************************************************************
 * Name: sec_ts_i2c_write
 *
 * Description:
 *   Write register address + data via I2C.
 *
 ****************************************************************************/

static int sec_ts_i2c_write(struct sec_ts_dev_s *dev, uint8_t reg,
                             const uint8_t *data, int len)
{
  struct i2c_msg_s msg;
  uint8_t *wbuf;
  int ret;
  int retry;

  wbuf = kmm_malloc(len + 1);
  if (wbuf == NULL)
    {
      return -ENOMEM;
    }

  wbuf[0] = reg;
  if (data != NULL && len > 0)
    {
      memcpy(wbuf + 1, data, len);
    }

  msg.frequency = SEC_TS_I2C_FREQ;
  msg.addr      = SEC_TS_I2C_ADDR;
  msg.flags     = 0;
  msg.buffer    = wbuf;
  msg.length    = len + 1;

  for (retry = 0; retry < SEC_TS_I2C_RETRY_CNT; retry++)
    {
      ret = I2C_TRANSFER(dev->i2c, &msg, 1);
      if (ret == OK)
        {
          kmm_free(wbuf);
          return OK;
        }

      nxsig_usleep(1000);
    }

  kmm_free(wbuf);
  ierr("SEC TS: I2C write reg 0x%02x failed: %d\n", reg, ret);
  return -EIO;
}

/****************************************************************************
 * Name: sec_ts_sw_reset
 *
 * Description:
 *   Perform software reset (0x42).
 *
 ****************************************************************************/

static int sec_ts_sw_reset(struct sec_ts_dev_s *dev)
{
  int ret;

  ret = sec_ts_i2c_write(dev, SEC_TS_CMD_SW_RESET, NULL, 0);
  if (ret < 0)
    {
      return ret;
    }

  /* Wait 100ms for reset to complete */

  nxsig_usleep(100000);

  return OK;
}

/****************************************************************************
 * Name: sec_ts_sense_on
 *
 * Description:
 *   Enable touch sensing (0x40).
 *
 ****************************************************************************/

static int sec_ts_sense_on(struct sec_ts_dev_s *dev)
{
  uint8_t val = 1;
  return sec_ts_i2c_write(dev, SEC_TS_CMD_SENSE_ON, &val, 1);
}

/****************************************************************************
 * Name: sec_ts_init_hw
 *
 * Description:
 *   Initialize the SEC TS controller hardware.
 *
 ****************************************************************************/

static int sec_ts_init_hw(struct sec_ts_dev_s *dev)
{
  uint8_t buf[4];
  int ret;

  /* 1. Read device ID to verify I2C communication */

  ret = sec_ts_i2c_read(dev, SEC_TS_READ_DEVICE_ID, buf, 4);
  if (ret < 0)
    {
      ierr("SEC TS: Failed to read device ID\n");
      return ret;
    }

  iinfo("SEC TS: Device ID = %02x %02x %02x %02x\n",
        buf[0], buf[1], buf[2], buf[3]);

  /* 2. Software reset */

  ret = sec_ts_sw_reset(dev);
  if (ret < 0)
    {
      ierr("SEC TS: Software reset failed\n");
      return ret;
    }

  /* 3. Set touch function: enable touch + hover */

  buf[0] = SEC_TS_BIT_SETFUNC_TOUCH | SEC_TS_BIT_SETFUNC_HOVER;
  ret = sec_ts_i2c_write(dev, SEC_TS_CMD_SET_TOUCHFUNCTION, buf, 1);
  if (ret < 0)
    {
      ierr("SEC TS: Failed to set touch function\n");
      return ret;
    }

  /* 4. Enable state management */

  buf[0] = 1;
  ret = sec_ts_i2c_write(dev, SEC_TS_CMD_STATEMANAGE_ON, buf, 1);
  if (ret < 0)
    {
      ierr("SEC TS: Failed to enable state management\n");
      return ret;
    }

  /* 5. Enable sensing */

  ret = sec_ts_sense_on(dev);
  if (ret < 0)
    {
      ierr("SEC TS: Failed to enable sensing\n");
      return ret;
    }

  nxsig_usleep(50000);

  dev->initialized = true;
  iinfo("SEC TS: Hardware init complete\n");

  return OK;
}

/****************************************************************************
 * Name: sec_ts_release_all_finger
 *
 * Description:
 *   Release all tracked touch points (used on error recovery).
 *
 ****************************************************************************/

static void sec_ts_release_all_finger(struct sec_ts_dev_s *dev)
{
  struct touch_sample_s sample;
  int i;

  memset(&sample, 0, sizeof(struct touch_sample_s));
  sample.npoints = 0;

  /* Send TOUCH_UP for each tracked touch */

  for (i = 0; i < MAX_SUPPORT_TOUCH_COUNT; i++)
    {
      if (dev->coord[i].action != SEC_TS_ACTION_NONE)
        {
          memset(&sample.point[0], 0, sizeof(struct touch_point_s));
          sample.point[0].id    = i;
          sample.point[0].flags = TOUCH_UP;
          sample.npoints        = 1;
          touch_event(dev->touch_lower.priv, &sample);
        }
    }

  dev->touch_count = 0;
  memset(dev->coord, 0, sizeof(dev->coord));
}

/****************************************************************************
 * Name: sec_ts_read_event
 *
 * Description:
 *   Read and process touch events from the controller.
 *   SEC TS protocol: read 8-byte event packets from 0x71.
 *
 *   Event format (coord event):
 *     byte[0]: [eid=2][ttype=3][tchsta=3]  — eid=1 for coord
 *     byte[1]: [nt=4][tid=4]               — touch ID
 *     byte[2]: x[11:4]                     — X upper 8 bits
 *     byte[3]: y[11:4]                     — Y upper 8 bits
 *     byte[4]: [x[3:0]=4][y[3:0]=4]       — X/Y lower nibbles
 *     byte[5]: z                           — width/pressure
 *     byte[6]: major                       — major axis
 *     byte[7]: minor                       — minor axis
 *
 ****************************************************************************/

static void sec_ts_read_event(struct sec_ts_dev_s *dev)
{
  uint8_t buf[SEC_TS_EVENT_SIZE];
  struct touch_sample_s sample;
  int ret;
  int event_id;
  int t_id;
  int action;
  uint16_t x;
  uint16_t y;
  int read_count;

  read_count = 0;

  memset(&sample, 0, sizeof(struct touch_sample_s));

  /* Read events until event buffer is empty */

  do
    {
      ret = sec_ts_i2c_read(dev, SEC_TS_READ_ONE_EVENT, buf, SEC_TS_EVENT_SIZE);
      if (ret < 0)
        {
          /* I2C error — release all touches to avoid stuck state */

          sec_ts_release_all_finger(dev);
          return;
        }

      event_id = buf[0] >> 6;

      if (event_id != SEC_TS_COORDINATE_EVENT)
        {
          /* Status event or gesture — ignore for now, no more events pending */
          break;
        }

      /* Parse coordinate event */

      t_id   = (buf[1] & 0x0f) - 1;       /* tid: 1-based, convert to 0-based */
      if (t_id < 0)
        {
          t_id = 0;
        }

      if (t_id >= MAX_SUPPORT_TOUCH_COUNT)
        {
          break;
        }

      x      = (buf[2] << 4) | (buf[4] >> 4);
      y      = (buf[3] << 4) | (buf[4] & 0x0f);
      action = buf[0] & 0x07;              /* tchsta field */

      /* Scale coordinates to display resolution */

      x = (uint16_t)((uint32_t)x * dev->max_x / 4096);
      y = (uint16_t)((uint32_t)y * dev->max_y / 4096);

      /* Handle touch action */

      if (action == SEC_TS_ACTION_RELEASE)
        {
          /* Touch release */

          memset(&sample, 0, sizeof(struct touch_sample_s));
          sample.npoints         = 1;
          sample.point[0].id     = t_id;
          sample.point[0].flags  = TOUCH_UP;
          sample.point[0].x      = dev->coord[t_id].x;
          sample.point[0].y      = dev->coord[t_id].y;

          touch_event(dev->touch_lower.priv, &sample);

          dev->coord[t_id].action = SEC_TS_ACTION_NONE;
          if (dev->touch_count > 0)
            {
              dev->touch_count--;
            }
        }
      else if (action == SEC_TS_ACTION_PRESS)
        {
          /* New touch press */

          dev->touch_count++;
          dev->coord[t_id].id     = t_id;
          dev->coord[t_id].action = action;
          dev->coord[t_id].x      = x;
          dev->coord[t_id].y      = y;
          dev->coord[t_id].z      = buf[5];

          memset(&sample, 0, sizeof(struct touch_sample_s));
          sample.npoints         = 1;
          sample.point[0].id     = t_id;
          sample.point[0].flags  = TOUCH_DOWN | TOUCH_POS_VALID;
          sample.point[0].x      = x;
          sample.point[0].y      = y;
          sample.point[0].pressure = buf[5];

          touch_event(dev->touch_lower.priv, &sample);
        }
      else if (action == SEC_TS_ACTION_MOVE)
        {
          /* Touch move */

          dev->coord[t_id].x = x;
          dev->coord[t_id].y = y;
          dev->coord[t_id].z = buf[5];

          memset(&sample, 0, sizeof(struct touch_sample_s));
          sample.npoints         = 1;
          sample.point[0].id     = t_id;
          sample.point[0].flags  = TOUCH_MOVE | TOUCH_POS_VALID;
          sample.point[0].x      = x;
          sample.point[0].y      = y;
          sample.point[0].pressure = buf[5];

          touch_event(dev->touch_lower.priv, &sample);
        }

      read_count++;
      if (read_count > MAX_EVENT_COUNT)
        {
          iwarn("SEC TS: Event buffer overflow, clearing\n");
          sec_ts_i2c_write(dev, SEC_TS_CMD_CLEAR_EVENT_STACK, NULL, 0);
          break;
        }
    }
  while (event_id == SEC_TS_COORDINATE_EVENT);
}

/****************************************************************************
 * Name: sec_ts_worker
 *
 * Description:
 *   Work queue polling function. Reads and processes touch events.
 *
 ****************************************************************************/

static void sec_ts_worker(void *arg)
{
  struct sec_ts_dev_s *dev = (struct sec_ts_dev_s *)arg;

  if (dev->suspended || !dev->initialized)
    {
      goto reschedule;
    }

  /* Read and process touch events */

  nxmutex_lock(&dev->lock);
  sec_ts_read_event(dev);
  nxmutex_unlock(&dev->lock);

reschedule:
  work_queue(HPWORK, &dev->work, sec_ts_worker, dev, SEC_TS_POLL_DELAY);
}

/****************************************************************************
 * Name: sec_ts_register_dev
 *
 * Description:
 *   Register the touch device with NuttX touch upper-half.
 *
 ****************************************************************************/

static int sec_ts_register_dev(struct sec_ts_dev_s *dev)
{
  dev->touch_lower.maxpoint = MAX_SUPPORT_TOUCH_COUNT;
  dev->touch_lower.priv     = dev;

  return touch_register(&dev->touch_lower, "/dev/input0",
                        MAX_SUPPORT_TOUCH_COUNT);
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sec_ts_initialize
 *
 * Description:
 *   Initialize the SEC TS touchscreen driver.
 *
 *   Called from board bringup (r528_bringup.c) with the I2C master
 *   interface already initialized.
 *
 * Parameters:
 *   i2c   - I2C master device (I2C0, PB2=SCL, PB3=SDA)
 *   max_x - Maximum X coordinate (e.g. 1080 for display width)
 *   max_y - Maximum Y coordinate (e.g. 2160 for display height)
 *
 * Returned Value:
 *   OK on success; negative errno on failure.
 *
 ****************************************************************************/

int sec_ts_initialize(struct i2c_master_s *i2c, uint16_t max_x,
                      uint16_t max_y)
{
  struct sec_ts_dev_s *dev = &g_sec_ts_dev;
  int ret;

  /* Initialize device structure */

  memset(dev, 0, sizeof(struct sec_ts_dev_s));
  dev->i2c   = i2c;
  dev->max_x = max_x;
  dev->max_y = max_y;

  /* Initialize mutex */

  ret = nxmutex_init(&dev->lock);
  if (ret < 0)
    {
      ierr("SEC TS: Failed to init mutex: %d\n", ret);
      return ret;
    }

  /* Initialize hardware */

  ret = sec_ts_init_hw(dev);
  if (ret < 0)
    {
      ierr("SEC TS: Hardware init failed: %d\n", ret);
      nxmutex_destroy(&dev->lock);
      return ret;
    }

  /* Register with NuttX touch subsystem */

  ret = sec_ts_register_dev(dev);
  if (ret < 0)
    {
      ierr("SEC TS: Failed to register touch device: %d\n", ret);
      nxmutex_destroy(&dev->lock);
      return ret;
    }

  /* Start work queue polling */

  work_queue(HPWORK, &dev->work, sec_ts_worker, dev, SEC_TS_POLL_DELAY);

  iinfo("SEC TS: Driver initialized (max_x=%d, max_y=%d)\n", max_x, max_y);

  return OK;
}

