lcd_dclk_freq  = 52;       // 52MHz
lcd_dsi_if     = 0;        // LCD_DSI_IF_VIDEO_MODE
lcd_dsi_lane   = 4;
lcd_dsi_format = 0;        // RGB888
lcd_dsi_clk_rate = 312;    // 52×24/4 = 312Mbps

