### 3.2 Panel 驱动 (init序列)

#### 7寸 (t070s140b.c)

```c
static void lcd_panel_init(u32 sel)
{
    // EK79007AD2 芯片初始化
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SOFT_RESET);  // 0x01
    delay_ms(120);
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);  // 0x11
    delay_ms(30);
    sunxi_lcd_dsi_gen_write_1para(sel, 0xB0, ...);  // 厂商寄存器
    sunxi_lcd_dsi_gen_write_1para(sel, 0xB1, ...);
    sunxi_lcd_dsi_gen_write_1para(sel, 0xB2, 0x30);  // Lane配置
    sunxi_lcd_dsi_gen_write_1para(sel, 0x80-0x86, ...);  // Gamma
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);  // 0x29
}
```

#### 6FHD (mipi_6fhd.c)

```c
static void lcd_panel_init(u32 sel)
{
    // 仅标准MIPI DCS命令（从RK3566设备树迁移）
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_EXIT_SLEEP_MODE);  // 0x11
    delay_ms(120);
    sunxi_lcd_dsi_dcs_write_0para(sel, DSI_DCS_SET_DISPLAY_ON);  // 0x29
    delay_ms(50);
}
```

