static void lcd_power_on(u32 sel)
{
    panel_reset(sel, LOW);                      // 拉低复位
    sunxi_lcd_power_enable(sel, DCDC1);         // 1.8V
    sunxi_lcd_power_enable(sel, DCDC3);         // 1.8V
    delay_ms(20);
    sunxi_lcd_pin_cfg(sel, 1);                  // 配置引脚
    delay_ms(50);
    panel_reset(sel, HIGH);                     // 释放复位
    delay_ms(20);
    panel_reset(sel, LOW);
    delay_ms(30);
