### 4.4 lcd_clk_config() 中的时钟计算

文件：`disp2/disp/de/disp_lcd.c:714-806`（非 ARCH_SUN8IW19 路径）

```c
static s32 lcd_clk_config(struct disp_device *lcd)
{
    dclk_rate = panel_info.lcd_dclk_freq * 1000000;  // 72MHz

    if (lcdp->panel_info.lcd_if == LCD_IF_DSI) {
        lcd_rate = dclk_rate * clk_info.dsi_div;    // 72×6 = 432MHz (TCON目标)
        pll_rate = lcd_rate * clk_info.lcd_div;     // 432×1 = 432MHz (PLL目标)
    }

    // 设置PLL父时钟
    disp_sys_clk_set_rate((u32) lcdp->clk_parent, (u32) pll_rate);  // PLL_VIDEO0_4X → 432MHz
    pll_rate_set = disp_sys_clk_get_rate((u32) lcdp->clk_parent);

    // 设置TCON时钟
    lcd_rate_set = pll_rate_set / clk_info.lcd_div;  // 432/1
    disp_sys_clk_set_rate(lcdp->clk_tcon_lcd, lcd_rate_set);  // TCON0 → 432MHz

    // 设置DSI时钟（视频模式）
    dsi_rate_set = pll_rate_set / clk_info.dsi_div;  // 432/6 = 72MHz
    dsi_rate_set = (clk_info.dsi_rate == 0) ? dsi_rate_set : clk_info.dsi_rate;
    // 注意：clk_tbl中dsi_rate=148500000 → 会覆盖为148.5MHz！

    disp_sys_clk_set_rate(lcdp->clk_mipi_dsi[0], dsi_rate_set);  // DSI总线时钟
}
```

### 4.5 D-PHY PLL 配置

文件：`disp2/disp/de/lowlevel_v2x/de_dsi.c:688`

```c
u32 dsi_comb_dphy_pll_set(__u32 sel, __u32 dclk, __u32 mode, __u32 format, __u32 lane)
{
    u64 frq;
    u8 pixel_bits[3][4] = {
        { 24, 24, 18, 16 },  // mode=0 (video/burst)
        { 24, 24, 16, 0  },  // mode=1 (command)
        { 24, 24, 18, 16 }   // mode=2
    };

    frq = dclk * pixel_bits[mode][format] / lane * 1000000;
    // 72 × 24 / 4 × 1000000 = 432,000,000 Hz

    // VCO约束：≥1.3GHz
    for (m = 0; frq_p <= vco;) {
        m++;
        frq_p = frq * m;
    }
    // 432×1=432 ≤ 1300 → continue
    // 432×2=864 ≤ 1300 → continue
    // 432×3=1296 ≤ 1300 → continue
    // 432×4=1728 > 1300 → stop, m=4, div_m0=3

    n = div_const(frq_p, 24000000);  // n = 1728/24 = 72

    // HS clock = 24MHz × n / (p+1) / (m0+1) = 24×72/1/4 = 432MHz
    // 但4倍VCO = 432×4 = 1728MHz... 超出VCO范围？
}
```

