s32 disp_lcd_gpio_init(struct disp_device *lcd)
{
    // ...
    // 2. GPIO请求
    for (i = 0; i < LCD_GPIO_NUM; i++)
        if (lcd_cfg->lcd_gpio_used[i])
            disp_sys_gpio_request(gpio_info, 1);  // 💥 极大概率死锁或越界崩溃在这里！
